/// </summary>
public static class UmbrellaApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("UMB-001", "UMB-DELAY: the reaction delay of a scheduled open or close is below SlowestWeatherChangeResponse (3) guest updates in the original, from the C runtime's rand() (0x870D38, called by the scheduling 0x613EA0); the delay's lengthening by the held balloon's share of life x DiscardBalloonPctModifier / 100 is the original's, the draw is not: a SplitMix64 hash of the guest's id and the park turn replaces rand() (the same bound, no draw from the shared world or guest streams, so a purchase's colour stays the only draw the extension takes), so the same park turn and guest give one fixed delay where the original's depended on the C runtime's hidden state"),
		("UMB-002", "UMB-VIEW: the scheduling (0x613EA0), the carrying out of a pending change (0x614010) and the draw routine (0x60AE00, which closes the umbrella at 0x60AF32 through 0x4055AB to 0x6142E0: state 2, sprite destroyed, bubble back to 2.5) all stand down for a guest standing on a kart or water track cell, read statically from two tests on the guest's cell index ([+7]*128 + [+5] + 1): 0x67F890 (thunk 0x40A344) on the 72-byte tile record, which takes the 40-byte record found through the tile record's first word (the array at game +0x11FFD8; an extension record, type 0xC or 0x11, goes on through its owner word +0x10 to its head) and applies the track predicate 0x6856D0 (types 0xB, 0xD, 0x10, 0x12, 0x19), and 0x685680 (thunk 0x405F01) on the 40-byte record of the same index at +0x11FFD8 (types 0xB, 0xC, 0x10, 0x11); both must hold; OpenTPW's walking guests never stand on a track cell (none of 71,591 sampled guest positions in Jungle, with and without a go-kart or boat track) and its riders are inside the ride, so the test is not modelled and nothing holds an umbrella change back but the day gate, the due time and the guest being inside an attraction; what is approximated is leaving the track-cell test out"),
